def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    additions = set()
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                pr, pc = r - dr, c - dc
                if pr >= 0 and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for er, ec, sr, sc in ((run[0][0], run[0][1], -dr, -dc), (run[-1][0], run[-1][1], dr, dc)):
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == grid[0][0]:
                        additions.add((rr, cc, color))
                        rr += sr
                        cc += sc
    for r, c, color in additions:
        out[r][c] = color
    return out
